<?php $pageTitle='Book a Car'; require_once __DIR__ . '/../includes/header.php'; $carId=isset($_GET['car_id'])?(int)$_GET['car_id']:(int)($_POST['car_id']??0); $car=find_car($carId); if(!$car){ set_flash('danger','Please select a valid rental car.'); redirect('/car-rent-sale-system/pages/cars-rent.php'); } if($_SERVER['REQUEST_METHOD']==='POST'){ $fullName=trim($_POST['full_name']); $email=trim($_POST['email']); $phone=trim($_POST['phone']); $pickup=$_POST['pickup_date']; $return=$_POST['return_date']; $location=trim($_POST['pickup_location']); if($fullName&&$email&&$phone&&$pickup&&$return){ $calc=booking_total($pickup,$return,(float)$car['rental_price_per_day']); $stmt=db()->prepare('INSERT INTO bookings (car_id, customer_name, email, phone, pickup_date, return_date, pickup_location, total_days, price_per_day, total_amount, booking_status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'); $stmt->execute([$car['id'],$fullName,$email,$phone,$pickup,$return,$location,$calc['days'],$car['rental_price_per_day'],$calc['total'],'pending']); set_flash('success','Booking submitted successfully.'); redirect('/car-rent-sale-system/pages/cars-rent.php'); } } ?><div class="container py-5"><div class="row justify-content-center"><div class="col-lg-8"><div class="form-box"><h2 class="section-title">Book <?= e($car['title']); ?></h2><form method="post"><input type="hidden" name="car_id" value="<?= (int)$car['id']; ?>"><input type="hidden" id="daily_rate" value="<?= e($car['rental_price_per_day']); ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Full Name</label><input class="form-control" name="full_name" required></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control" name="email" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" required></div><div class="col-md-6"><label class="form-label">Pickup Location</label><input class="form-control" name="pickup_location" required></div><div class="col-md-6"><label class="form-label">Pickup Date</label><input type="date" id="pickup_date" class="form-control" name="pickup_date" required></div><div class="col-md-6"><label class="form-label">Return Date</label><input type="date" id="return_date" class="form-control" name="return_date" required></div><div class="col-md-6"><label class="form-label">Estimated Total</label><input id="estimated_total" class="form-control" readonly value="0.00"></div><div class="col-12"><button class="btn btn-primary">Submit Booking</button></div></div></form></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
